import{c as l,S as i,j as a,m as r}from"./chunks/framework.8aa1YH_s.js";const g=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 19 (FİNAL): Cümle Türleri ve Yapısal Analiz","description":"","frontmatter":{},"headers":[],"relativePath":"19 (FİNAL) Cümle Türleri ve Yapısal Analiz.md","filePath":"19 (FİNAL) Cümle Türleri ve Yapısal Analiz.md"}'),n={name:"19 (FİNAL) Cümle Türleri ve Yapısal Analiz.md"};function m(s,e,t,k,o,d){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="turk-dil-bilgisi-serisi-19-final-cumle-turleri-ve-yapısal-analiz" tabindex="-1">Türk Dil Bilgisi Serisi - 19 (FİNAL): Cümle Türleri ve Yapısal Analiz <a class="header-anchor" href="#turk-dil-bilgisi-serisi-19-final-cumle-turleri-ve-yapısal-analiz" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 19 (FİNAL): Cümle Türleri ve Yapısal Analiz”">​</a></h1><p>Ses bilgisinden başladık, kelimelerin köklerine indik, eklerle büyüdük, kelime türleriyle anlam kazandık ve nihayet Türk dil bilgisinin en tepe noktasına, yani büyük finale ulaştık: <strong>Cümle Türleri</strong>.</p><p>Prof. Dr. Muharrem Ergin’e göre cümleler sadece yan yana gelmiş kelimeler değildir; her bir cümle kendi içinde mimari bir yapıdır. Dil biliminde cümleler; yükleminin türüne, yükleminin yerine, anlamlarına ve en önemlisi <strong>yapılarına</strong> göre 4 farklı kritere göre sınıflandırılır.</p><p>İşte Türkçenin cümle mimarisinin haritası:</p><hr><h2 id="_1-yukleminin-turune-gore-cumleler" tabindex="-1">1. Yükleminin Türüne Göre Cümleler <a class="header-anchor" href="#_1-yukleminin-turune-gore-cumleler" aria-label="Permalink to “1. Yükleminin Türüne Göre Cümleler”">​</a></h2><p>Cümlenin kalbi olan yüklemin hangi kelime soylu olduğuna bakılır:</p><ol><li><strong>Fiil (Eylem) Cümlesi:</strong> Yüklemi çekimli bir fiil olan cümlelerdir. Türkçede dinamizmi sağlar. <ul><li><em>Örnek:</em> Bütün gece durmadan kod <strong>yazdı</strong>. (<em>Yazmak = Fiil</em>)</li></ul></li><li><strong>İsim (Ad) Cümlesi:</strong> Yüklemi ek-fiil alarak yüklem olmuş bir isim, sıfat, zamir veya tamlama olan cümlelerdir. Durum bildirir. <ul><li><em>Örnek:</em> Onun en büyük tutkusu <strong>bilgisayardı</strong>. (<em>Bilgisayar = İsim</em>)</li></ul></li></ol><hr><h2 id="_2-yukleminin-yerine-oge-dizilisine-gore-cumleler" tabindex="-1">2. Yükleminin Yerine (Öge Dizilişine) Göre Cümleler <a class="header-anchor" href="#_2-yukleminin-yerine-oge-dizilisine-gore-cumleler" aria-label="Permalink to “2. Yükleminin Yerine (Öge Dizilişine) Göre Cümleler”">​</a></h2><p>Türkçenin asli kuralı yüklemin sonda olmasıdır, ancak kullanıma göre değişebilir:</p><ol><li><strong>Kurallı (Düz) Cümle:</strong> Yüklemi cümlenin tam <strong>sonunda</strong> yer alan nesnel ve standart cümlelerdir. <ul><li><em>Örnek:</em> Beşiktaş bu akşam harika bir oyun <strong>sergiledi</strong>.</li></ul></li><li><strong>Devrik Cümle:</strong> Yüklemi cümlenin sonunda <strong>olmayan</strong> (başında veya ortasında yer alan), şiirsel veya günlük konuşma dilinde vurguyu artırmak için kullanılan cümlelerdir. <ul><li><em>Örnek:</em> <strong>Açıldı</strong> aniden Brüksel uçağının kapıları.</li></ul></li><li><strong>Eksiltili Cümle:</strong> Yüklemi yazılmamış, okuyucunun zihninde tamamlaması beklenen cümlelerdir. Sonu genellikle üç nokta (<code>...</code>) ile biter. <ul><li><em>Örnek:</em> Az veren candan, çok veren <strong>maldan (verir)...</strong></li></ul></li></ol><hr><h2 id="_3-anlamlarına-gore-cumleler" tabindex="-1">3. Anlamlarına Göre Cümleler <a class="header-anchor" href="#_3-anlamlarına-gore-cumleler" aria-label="Permalink to “3. Anlamlarına Göre Cümleler”">​</a></h2><p>Cümlenin bildirdiği hükmün gerçekleşme durumuna veya amacına bakılır:</p><ol><li><strong>Olumlu Cümle:</strong> Yüklemde bahsedilen işin, eylemin gerçekleştiğini veya söz konusu durumun var olduğunu bildiren cümlelerdir. <ul><li><em>Örnek:</em> Yeni güncellemeyi başarıyla <strong>yayınladık</strong>.</li></ul></li><li><strong>Olumsuz Cümle:</strong> Eylemin gerçekleşmediğini veya durumun var olmadığını bildirir. Fiillerde <code>-ma/-me</code>, isimlerde ise <code>değil</code> veya <code>yok</code> ile kurulur. <ul><li><em>Örnek:</em> Aradığın evraklar bende <strong>değil</strong>. / Bugün hiç çalış-<strong>ma</strong>-dı.</li></ul></li><li><strong>Soru Cümlesi:</strong> Bilgi almak veya onaylatmak amacıyla kurulan cümlelerdir. <ul><li><em>Örnek:</em> Toplantı saat kaçta başlayacak?</li></ul></li></ol><hr><h2 id="_4-yapılarına-gore-cumleler-en-kritik-bolum" tabindex="-1">4. Yapılarına Göre Cümleler (En Kritik Bölüm) <a class="header-anchor" href="#_4-yapılarına-gore-cumleler-en-kritik-bolum" aria-label="Permalink to “4. Yapılarına Göre Cümleler (En Kritik Bölüm)”">​</a></h2><p>Muharrem Ergin sistematiğinde cümlenin yapısı, içindeki <strong>hüküm sayısına</strong> ve yan cümleciklerin durumuna göre belirlenir. 4 temel yapı vardır:</p><h3 id="a-basit-cumle" tabindex="-1">A) Basit Cümle <a class="header-anchor" href="#a-basit-cumle" aria-label="Permalink to “A) Basit Cümle”">​</a></h3><p>İçinde <strong>sadece bir tek yüklem (tek bir hüküm)</strong> bulunan, fiilimsi veya başka bir yan cümle barındırmayan tertemiz cümlelerdir.</p><ul><li><em>Örnek:</em> <em>Ahmet dün akşam erkenden uyudu.</em> (Tek yüklem var, başka hareket yok).</li></ul><h3 id="b-birlesik-cumle" tabindex="-1">B) Birleşik Cümle <a class="header-anchor" href="#b-birlesik-cumle" aria-label="Permalink to “B) Birleşik Cümle”">​</a></h3><p>İçinde bir temel yüklemin yanı sıra, ona bağlı olan ve en az bir <strong>yan cümlecik (genellikle fiilimsi)</strong> barındıran cümlelerdir.</p><ul><li><em>Örnek:</em> <em>Kodu <strong>inceleyen</strong> mühendis hatayı buldu.</em> * <em>Temel Cümle:</em> Hatayı buldu (Yüklem). <ul><li><em>Yan Cümle:</em> Kodu inceleyen (Fiilimsi ile kurulmuş yan cümlecik).</li></ul></li></ul><h3 id="c-sıralı-cumle" tabindex="-1">C) Sıralı Cümle <a class="header-anchor" href="#c-sıralı-cumle" aria-label="Permalink to “C) Sıralı Cümle”">​</a></h3><p>Bağımsız iki veya daha fazla cümlenin birbirine <strong>virgül (,)</strong> veya <strong>noktalı virgül (😉</strong> ile bağlanarak tek bir satırda sıralanmasıdır.</p><ul><li><em>Örnek:</em> <em>Gözlerimi açtım (1. Cümle), etrafa baktım (2. Cümle), kimseyi göremedim (3. Cümle).</em></li></ul><h3 id="d-baglı-cumle" tabindex="-1">D) Bağlı Cümle <a class="header-anchor" href="#d-baglı-cumle" aria-label="Permalink to “D) Bağlı Cümle”">​</a></h3><p>Aralarında anlam bağı bulunan bağımsız cümlelerin birbirine virgülle değil, doğrudan bir <strong>bağlaçla (ve, ama, çünkü, fakat...)</strong> bağlanması hadisesidir.</p><ul><li><em>Örnek:</em> <em>Çok çalıştı (1. Cümle) <strong>ama</strong> projeyi yetiştiremedi (2. Cümle).</em></li></ul><hr><h2 id="🏆-kapanıs-ozeti-ve-tebrik" tabindex="-1">🏆 Kapanış Özeti ve Tebrik <a class="header-anchor" href="#🏆-kapanıs-ozeti-ve-tebrik" aria-label="Permalink to “🏆 Kapanış Özeti ve Tebrik”">​</a></h2><p>Böylelikle, Türk dil biliminin efsane profesörü <strong>Prof. Dr. Muharrem Ergin</strong>&#39;in sistematiğine sadık kalarak hazırladığımız <strong>19 bölümlük Türk Dil Bilgisi Yazı Serisinin</strong> sonuna geldik.</p><p>Seslerin o gizemli dünyasından başladık; kelimelerin yapısını, eklerin muazzam matematiğini çözdük; kelime türleriyle cümleleri renklendirdik ve en sonunda cümlenin o muhteşef mimarisiyle binayı tamamladık. Türkçe, kuralları ve simetrisiyle adeta yaşayan bir matematik harikasıdır.</p><p>Bu seriyi baştan sona okuyan, dille yaşayan ve dilini koruyan tüm okurlara gönülden teşekkürler. Kaleminiz keskin, Türkçeniz her daim ahenkli olsun!</p>',36)])])}const c=l(n,[["render",m]]);export{g as __pageData,c as default};
